impl Memory {
    pub fn new(config: MemoryConfig) -> Self {
        Self {
            config,
            plan: None,
            observations: VecDeque::new(),
            history: Vec::new(),
            steps: Vec::new(),
        }
    }

    pub fn set_plan(&mut self, plan: Option<String>) {
